package com.ahope.ds.web.superadmin.mngTerms.service;

import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.stereotype.Service;
import org.springframework.transaction.TransactionStatus;
import org.springframework.transaction.support.DefaultTransactionDefinition;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.web.service.CommonService;
import com.ahope.ds.web.superadmin.mngTerms.dao.MngTermsDAO;

@Service
public class MngTermsService extends CommonService {

	@Autowired
	private MngTermsDAO mngTermsDAO;
	
	@Autowired
	private DataSourceTransactionManager transactionManager;
	
	//관리자 약관 상세
	public ResultMap getMngTerms(ParamMap param) {
		ResultMap result = mngTermsDAO.getMngTerms(param);
		return result;
	}
	
	//관리자 약관 등록
	public ResultMap createMngTerms(ParamMap param) {
		ResultMap result = new ResultMap();
		TransactionStatus transactionStatus = transactionManager.getTransaction(new DefaultTransactionDefinition());
		try {
			long mngTermsSeq = mngTermsDAO.getNextMngTermsSeq();
			param.put("regAccountId", param.getSessionAttribute("loginId"));
			param.put("regAccountSeq", param.getSessionAttribute("loginAccountSeq"));
			param.put("mngTermsSeq", mngTermsSeq);
			param.put("link", param.getString("link"));
			mngTermsDAO.createMngTerms(param);
						
			result.setErr("000");
			transactionManager.commit(transactionStatus);
		} catch (Exception e) {
			e.printStackTrace();
			transactionManager.rollback(transactionStatus);
			result.setErr("001");
			logger.error(e.getMessage());
		}
		return result;
	}
	
	//약관 목록 조회
	public ResultMap getMngAgreeTermsList(ParamMap param) {
		ResultMap result = new ResultMap();
		
		try {
			List<ParamMap> mngTermsList = mngTermsDAO.getMngAgreeTermsList(param);
			Integer mngTermsListCount = mngTermsDAO.getMngAgreeTermsListCount(param);
		
			result.put("iTotalRecords", mngTermsListCount);
			result.put("iTotalDisplayRecords", mngTermsListCount);		
			result.put("aaData", mngTermsList);
		} catch (Exception e) {
			result.setErr("999");
			result.setErrMsg("Unknown error");
			logger.error(e.getMessage());
		}
		
		return result;
	}
	
	//약관 상세
	public ResultMap getMngAgreeTermsDetail(Long mngAgreeTermsSeq) {
		ResultMap result = new ResultMap();
	
		try {
			result.put("mngTerms", mngTermsDAO.getMngAgreeTermsDetail(mngAgreeTermsSeq));
		} catch (Exception e) {
			result.setErr("999");
			result.setErrMsg("Unknown error");
			logger.error(e.getMessage());
		}
		
		return result;
	}
	
	//약관 등록
	public ResultMap createMngAgreeTerms(ParamMap param) throws LogicException {
		ResultMap result = new ResultMap();
		Boolean isRecent = mngTermsDAO.checkMngAgreeTermsIsRecent(param.getInt("version"));
		
		if (!isRecent) {
			throw new LogicException("Version must be current or higher", "001");
		}
		
		TransactionStatus transactionStatus = transactionManager.getTransaction(new DefaultTransactionDefinition());

		try {
			param.put("regAccountId", param.getSessionAttribute("loginId"));
			param.put("regAccountSeq", param.getSessionAttribute("loginAccountSeq"));
			param.put("mngAgreeTermsSeq", mngTermsDAO.getNextMngAgreeTermsSeq());
			mngTermsDAO.createMngAgreeTerms(param);
			transactionManager.commit(transactionStatus);
		} catch (Exception e) {
			e.printStackTrace();
			transactionManager.rollback(transactionStatus);
			result.setErr("999");
			result.setErrMsg("Unknown error");
		}
		return result;
	}
}
