	public long getNextMngTermsSeq() throws Exception {
		return defaultSelectOne("mngTerms.getNextMngTermsSeq");
	}
	
	public int createMngTerms(ParamMap param) {
		return defaultInsert("mngTerms.createMngTerms", param);
	}
	
	public ResultMap getMngTerms(ParamMap param) {
		return defaultSelectOne("mngTerms.getMngTerms", param);
	}
	
	
	
	//약관 목록 수 조회
	public Integer getMngAgreeTermsListCount(ParamMap param) {
		return selectOne("mngTerms.getMngAgreeTermsListCount", param);
	}

	//약관 목록 조회
	public List<ParamMap> getMngAgreeTermsList(ParamMap param) {
		return selectList("mngTerms.getMngAgreeTermsList", param);
	}
	
	//약관 상세 정보 조회
	public ResultMap getMngAgreeTermsDetail(Long mngAgreeTermsSeq) {
		return selectOne("mngTerms.getMngAgreeTermsDetail", mngAgreeTermsSeq);
	}
	
	//약관 등록 시 버전 검증
	public Boolean checkMngAgreeTermsIsRecent(Integer version) {
		return selectOne("mngTerms.checkMngAgreeTermsIsRecent", version);
	}
	
	public long getNextMngAgreeTermsSeq() throws Exception {
		return defaultSelectOne("mngTerms.getNextMngAgreeTermsSeq");
	}
	
	//약관 등록
	public Integer createMngAgreeTerms(ParamMap param) {
		return insert("mngTerms.createMngAgreeTerms",  param);
	}
	
}

