package com.ahope.ds.common.bean;

import java.math.BigDecimal;
import java.util.HashMap;

import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.exception.RuntimeLogicException;
import com.ahope.ds.common.util.CommonUtil;

public class ResultMap extends HashMap<String, Object>{

	private static final long serialVersionUID = 1L;

	public ResultMap() {
		super();
		this.put("err", "000");
	}
	
	public ResultMap(String code){
		super();
		this.put("err", code);
	}
	
	public ResultMap(String code, String msg){
		super();
		this.put("err", code);
		this.put("errMsg", msg);
	}

	public void setCode(Exception e) {
		this.put("err", "1000");
		this.put("errMsg", e.getMessage());
	}
	
	public void setCode(LogicException le) {
		this.put("err", (CommonUtil.isNull(le.getCode()) ? "1000" : le.getCode()));
		this.put("errMsg", le.getMessage());
	}
	
	public void setCode(RuntimeLogicException rle) {
		this.put("err", (CommonUtil.isNull(rle.getCode()) ? "1000" : rle.getCode()));
		this.put("errMsg", rle.getMessage());
	}
	
	public String getCode() {
		return CommonUtil.nvl((String)this.get("err"));
	}

	public void setErr(String err) {
		this.put("err", err);
	}

	public String getErrMsg() {
		return CommonUtil.nvl((String)this.get("errMsg"));
	}

	public void setErrMsg(String errMsg) {
		this.put("errMsg", errMsg);
	}
	
	/**
	 * Object 값 반환 
	 * */
	public Object get(String key) {
		
		Object result = super.get(key);
		
		if (result == null) {
			result = "";
		}
		
		return result;
	}
	
	/**
	 * Long 반환
	 * */
	public long getLong(String key) {
		
		long result = 0;
		
		Object obj = super.get(key);
		
		try{
			
			if(obj != null) {
				
				if(obj instanceof String) {
					result = Long.parseLong((String)obj);
				} else if(obj instanceof Number) {
					result = ((Number)obj).longValue();
				}
			}
			
		} catch(Exception e) {
			result = 0;
		}
		
		return result;
	}
	
	/**
	 * Boolean 값 반환
	 * */
	public Boolean getBoolean(String key) {
		
		boolean result = false;
		
		Object obj = super.get(key);
		try{
			
			if(obj != null) {
				if (obj instanceof Boolean) {
					if ((Boolean)obj) {
						result = true;
					} else {
						result = false;
					}
				}
			}
			
		} catch(Exception e) {
			result = false;
		}
		
		return result;
	}
	
	/**
	 * Integer 반환
	 * */
	public int getInt(String key) {
		
		int result = 0;
		Object obj = super.get(key);
		
		try{
			if(obj != null) {
				if(obj instanceof String) {
					result = Integer.parseInt((String)obj);
				} else if(obj instanceof Number) {
					result = ((Number)obj).intValue();
				}
			}
		} catch(Exception e) {
			result = 0;
		}
		
		return result;
	}
	
	/**
	 * String 값 반환
	 **/
	public String getString(String key) {
		String result = "";
		Object obj = super.get(key);
		try {
			if (obj != null) {
				if (obj instanceof String) {
					result = (String)obj;
				} else if (obj instanceof Boolean) {
					result = String.valueOf((Boolean)obj);
				} else if (obj instanceof Integer) {
					result = String.valueOf((Integer)obj);
				} else if (obj instanceof Long) {
					result = String.valueOf((Long)obj);
				} else if (obj instanceof Short) {
					result = String.valueOf((Short)obj);
				} else if (obj instanceof Float) {
					result = String.valueOf((Float)obj);
				} else if (obj instanceof Double) {
					result = String.valueOf((Double)obj);
				} else if (obj instanceof Character) {
					result = String.valueOf((Character)obj);
				} else if (obj instanceof BigDecimal) {
					result = ((BigDecimal)obj).toString();
				} else {
					result = obj.toString();
				}
			}
		} catch(Exception e) {
			result = "";
		}
		return result;
	}
	
	public boolean strToBoolean(String str) {
		boolean result = false;
		if (str.toLowerCase().equals("true")) {
			result = true;
		} else if (str.toLowerCase().equals("false")) {
			result = false;
		}
		return result;
	}
}
