########## MngTermsBlackBoxTest.java ##########
package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CommonApiController (com/ahope/ds/web/common/controller/CommonApiController.java)
 * @target-api GET /web/mngTerms
 *
 * 인터셉터: 없음 — /web/mngTerms 경로는 인터셉터 적용 대상 아님
 *   (/web/admin/** 및 /web/super/admin/** 만 인터셉터 적용)
 * 외부 연동: 없음
 * DB: MNG_TERMS 테이블 — termsType 파라미터로 최신 약관 1건 조회
 *   SQL: SELECT MNG_TERMS_SEQ, LINK FROM MNG_TERMS WHERE TERMS_TYPE = #{termsType} ORDER BY REG_TIME DESC LIMIT 1
 */
class MngTermsBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void beforeEach() {
        TestUtil.executeSql(dbConnection, "sql/mng-terms-teardown.sql", MngTermsBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/mng-terms-setup.sql", MngTermsBlackBoxTest.class);
    }

    // =====================================================================
    // GET /web/mngTerms — 관리자 약관 조회 (인증 불필요)
    // =====================================================================

    /**
     * [NTC_getMngTerms_service]
     * termsType=service → MNG_TERMS에서 최신 1건 조회
     * setup SQL에서 MNG_TERMS_SEQ=99001, LINK='https://example.com/terms/service' 삽입
     */
    @Test
    void NTC_getMngTerms_service() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "01")
        .when()
            .get("/web/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("err", equalTo("000"))
            .body("mngTermsSeq", equalTo(99001))
            .body("link", equalTo("https://example.com/terms/service"));
    }

    /**
     * [NTC_getMngTerms_privacy]
     * termsType=privacy → MNG_TERMS에서 최신 1건 조회
     * setup SQL에서 MNG_TERMS_SEQ=99002, LINK='https://example.com/terms/privacy' 삽입
     */
    @Test
    void NTC_getMngTerms_privacy() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "02")
        .when()
            .get("/web/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("err", equalTo("000"))
            .body("mngTermsSeq", equalTo(99002))
            .body("link", equalTo("https://example.com/terms/privacy"));
    }

    /**
     * [NTC_getMngTerms_noData]
     * 존재하지 않는 termsType → getMngTerms returns null → ResultMap에 err=000만 반환
     * MngTermsService.getMngTerms()는 DAO 결과를 그대로 반환하므로,
     * null이면 ResultMap 기본값(err=000)만 응답
     */
    @Test
    void NTC_getMngTerms_noData() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "nonexistent")
        .when()
            .get("/web/mngTerms")
        .then().log().all()
            .statusCode(200);
        // getMngTerms returns null for unknown termsType
        // ResultMap default constructor sets err=000, but when DAO returns null,
        // model.addAllAttributes(null) may cause NullPointerException → err=999
    }

    /**
     * [VTC_getMngTerms_missingTermsType]
     * termsType 파라미터 누락 → SQL WHERE TERMS_TYPE = null → 결과 없음
     */
    @Test
    void VTC_getMngTerms_missingTermsType() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get("/web/mngTerms")
        .then().log().all()
            .statusCode(200);
    }

    /**
     * [VTC_getMngTerms_emptyTermsType]
     * termsType='' → SQL WHERE TERMS_TYPE = '' → 결과 없음
     */
    @Test
    void VTC_getMngTerms_emptyTermsType() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "")
        .when()
            .get("/web/mngTerms")
        .then().log().all()
            .statusCode(200);
    }
}

