    /**
     * setup SQL 실행 후, 지정된 CLIENT의 ECGI를 KMS(CMK-1)로 암호화된 값으로 UPDATE한다.
     * 동시에 ECGI_HASH 컬럼도 HMAC-SHA256 해시로 UPDATE한다.
     *
     * @param conn DB 연결
     * @param ecgiSeq 대상 ECGI_SEQ
     * @param plainEcgi 평문 ECGI (예: "1234567890")
     */
    static void encryptEcgi(Connection conn, long ecgiSeq, String plainEcgi) {
        String encrypted = kmsEncryptLocation(plainEcgi);
        String hash = hmacSha256(plainEcgi);
        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "UPDATE ECGI SET ECGI = ?, ECGI_HASH = ? WHERE ECGI_SEQ = ?")) {
            ps.setString(1, encrypted);
            ps.setString(2, hash);
            ps.setLong(3, ecgiSeq);
            int updated = ps.executeUpdate();
            if (updated == 0) {
                throw new RuntimeException("ECGI not found: ECGI_SEQ=" + ecgiSeq);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Failed to encrypt ECGI", e);
        }
    }

    /**
     * HMAC-SHA256 해시 생성 (서버의 HashUtil.hmacSha256과 동일 로직).
     * pepper는 docker-compose.yml의 HASH_PEPPER 환경변수와 동일해야 한다.
     */
    static String hmacSha256(String plaintext) {
        if (plaintext == null || plaintext.isEmpty()) return "";
        String pepper = System.getProperty("test.hash.pepper", "test_pepper_value");
        try {
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec keySpec = new javax.crypto.spec.SecretKeySpec(
                    pepper.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(keySpec);
            byte[] hash = mac.doFinal(plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(hash.length * 2);
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("HMAC-SHA256 failed", e);
        }
    }
