package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller MngTermsController (src/main/java/com/ahope/ds/web/superadmin/mngTerms/controller/MngTermsController.java)
 * @target-api GET /web/super/admin/mngTerms  (handler: getNotice → MngTermsService.getMngTerms)
 *
 * 인터셉터: SuperAdminLoginInterceptor (/web/super/admin/**)
 *   - 세션 loginAccountSeq 로 ACCOUNT.AUTHZ 조회, Authz.SYSTEM('07') 만 mngTerms 화이트리스트 통과
 *     (SUPER='01' 은 /clients,/traffic,... 화이트리스트에만 있어 mngTerms 접근 시 403)
 *   - 세션 없음 + 非 /ajax 경로 → res.sendRedirect("/web/login") → HTTP 302
 * 외부 연동: 없음 (detect-external-calls --include-di-analysis → must_mock=[]) → WireMock 스텁 불필요
 * DB: MNG_TERMS — termsType 파라미터로 최신 약관 1건 조회
 *   SQL: SELECT MNG_TERMS_SEQ AS mngTermsSeq, LINK AS link FROM MNG_TERMS
 *        WHERE TERMS_TYPE = #{termsType} ORDER BY REG_TIME DESC LIMIT 1
 *   응답 envelope: ResultMap(default err="000") + mngTermsSeq + link.
 *   조회 결과 없음(null) → model.addAllAttributes(null) 무시 → 빈 JSON {} (mngTermsSeq/link/err 부재).
 *
 * 데이터 격리: 전용 ID 대역(ACCOUNT_SEQ=96560, MNG_TERMS_SEQ=96561~96564) 사용 →
 *   AdminMngTermsBlackBoxTest(99004/96001~) 및 다른 약관 테스트와 충돌하지 않음.
 * 읽기 전용 GET 이므로 API 호출 후 DB 상태 변경 검증(JDBC)은 해당 없음.
 */
class SuperAdminMngTermsGetBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/super-admin-mng-terms-get-teardown.sql", SuperAdminMngTermsGetBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/super-admin-mng-terms-get-setup.sql", SuperAdminMngTermsGetBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "mngtermsget", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/super-admin-mng-terms-get-teardown.sql", SuperAdminMngTermsGetBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void beforeEach() {
        TestUtil.executeSql(dbConnection, "sql/super-admin-mng-terms-get-data-setup.sql", SuperAdminMngTermsGetBlackBoxTest.class);
    }

    // =====================================================================
    // NTC — Happy Path (SYSTEM 관리자 세션으로 조회)
    // =====================================================================

    /**
     * [NTC_getNotice_type01_returnsLatest]
     * termsType='01' 은 2건(96561 구, 96562 신) 존재 → ORDER BY REG_TIME DESC LIMIT 1 → 최신 96562 만 반환.
     */
    @Test
    void NTC_getNotice_type01_returnsLatest() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "01")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("err", equalTo("000"))
            .body("mngTermsSeq", equalTo(96562))
            .body("link", equalTo("https://example.com/get/service-new"));
    }

    /**
     * [NTC_getNotice_type02_privacy]
     * termsType='02' → 96563 반환.
     */
    @Test
    void NTC_getNotice_type02_privacy() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "02")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("err", equalTo("000"))
            .body("mngTermsSeq", equalTo(96563))
            .body("link", equalTo("https://example.com/get/privacy"));
    }

    /**
     * [NTC_getNotice_type03_single]
     * termsType='03' → 96564 반환 (임의 2자리 타입도 정상 조회).
     */
    @Test
    void NTC_getNotice_type03_single() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "03")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("err", equalTo("000"))
            .body("mngTermsSeq", equalTo(96564))
            .body("link", equalTo("https://example.com/get/location"));
    }

    // =====================================================================
    // VTC — RED 파라미터 termsType 변조 (DB_WHERE 조건)
    // =====================================================================

    /**
     * [VTC_termsType_NULL]
     * termsType 파라미터 누락 → WHERE TERMS_TYPE = null → 매칭 0건 → getMngTerms null →
     * model.addAllAttributes(null) 무시 → 빈 JSON {} (mngTermsSeq/link 부재).
     */
    @Test
    void VTC_termsType_NULL() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("link", nullValue());
    }

    /**
     * [VTC_termsType_EMPTY]
     * termsType='' → WHERE TERMS_TYPE = '' → 매칭 0건 → 빈 JSON {}.
     */
    @Test
    void VTC_termsType_EMPTY() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("link", nullValue());
    }

    // =====================================================================
    // ATC — 인증/인가 예외
    // =====================================================================

    /**
     * [ATC_getNotice_noSession]
     * 세션 쿠키 없음 → SuperAdminLoginInterceptor.preHandle: loginAccountSeq 없음 + 非 /ajax 경로 →
     * res.sendRedirect("/web/login") → HTTP 302 (RestAssured 기본은 리다이렉트를 따르지 않음).
     */
    @Test
    void ATC_getNotice_noSession() {
        given().log().all().baseUri(BASE_URL)
            .redirects().follow(false)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "01")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(302);
    }
}

